create policy documents_update_editor
  on public.documents
  for update
  to authenticated
  using (deleted_at is null and public.is_team_editor(team_id))
  with check (public.is_team_editor(team_id));

-- R6: only the creator can (hard) delete
create policy documents_delete_creator
  on public.documents
  for delete
  to authenticated
  using (created_by = auth.uid() and deleted_at is null);

-- Trigger: protect created_by and restrict soft-delete to the creator
create or replace function public.documents_guard_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') not in ('authenticated', 'anon') then
    return new;
  end if;

  if new.created_by is distinct from old.created_by then
    raise exception 'created_by cannot be changed';
  end if;

  if new.deleted_at is distinct from old.deleted_at then
    if old.created_by is distinct from auth.uid() then
      raise exception 'only the creator can delete this document';
    end if;
  end if;

  return new;
end;
$$;

create trigger documents_guard_update
  before update on public.documents
  for each row
  execute function public.documents_guard_update();
