```sql
-- =========================================================================
-- Enable RLS
-- =========================================================================
alter table public.teams        enable row level security;
alter table public.team_members enable row level security;
alter table public.documents    enable row level security;

-- =========================================================================
-- Privileges
-- R8: anon gets nothing. R7: authenticated can only read teams/memberships.
-- R9: service_role bypasses RLS and keeps its existing grants.
-- =========================================================================
revoke all on public.teams        from anon, public;
revoke all on public.team_members from anon, public;
revoke all on public.documents    from anon, public;

revoke all on public.teams        from authenticated;
revoke all on public.team_members from authenticated;
revoke all on public.documents    from authenticated;

grant select                         on public.teams        to authenticated;
grant select                         on public.team_members to authenticated;
grant select, insert, update, delete on public.documents    to authenticated;

-- =========================================================================
-- Helper functions (security definer: no RLS recursion, fast index lookups)
-- =========================================================================
create or replace function public.is_team_member(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
  );
$$;

create or replace function public.is_team_editor(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
      and tm.role = 'editor'
  );
$$;

revoke all on function public.is_team_member(bigint) from public, anon;
revoke all on function public.is_team_editor(bigint) from public, anon;
grant execute on function public.is_team_member(bigint) to authenticated;
grant execute on function public.is_team_editor(bigint) to authenticated;

-- =========================================================================
-- teams (R1, R7)
-- =========================================================================
create policy "teams_select_members"
  on public.teams
  for select
  to authenticated
  using ( public.is_team_member(id) );

-- =========================================================================
-- team_members (R2, R7)
-- =========================================================================
create policy "team_members_select_own"
  on public.team_members
  for select
  to authenticated
  using ( user_id = (select auth.uid()) );

-- =========================================================================
-- documents
-- =========================================================================

-- R3: members read non-deleted docs of their teams
create policy "documents_select_members"
  on public.documents
  for select
  to authenticated
  using (
    deleted_at is null
    and public.is_team_member(team_id)
  );

-- R4: editors create docs in their teams, created_by = self, not pre-deleted
create policy "documents_insert_editors"
  on public.documents
  for insert
  to authenticated
  with check (
    created_by = (select auth.uid())
    and deleted_at is null
    and public.is_team_editor(team_id)
  );

-- R5: editors edit non-deleted docs in their teams; result must stay in an
-- editor team. (Soft-delete / created_by changes are policed by trigger.)
create policy "documents_update_editors"
  on public.documents
  for update
  to authenticated
  using (
    deleted_at is null
    and public.is_team_editor(team_id)
  )
  with check (
    public.is_team_editor(team_id)
  );

-- R6: only the creator may hard-delete
create policy "documents_delete_creator"
  on public.documents
  for delete
  to authenticated
  using (
    deleted_at is null
    and created_by = (select auth.uid())
    and public.is_team_member(team_id)
  );

-- =========================================================================
-- Trigger: protect created_by and deleted_at for app users
--   * created_by is immutable (prevents hijacking delete rights)
--   * only the creator may set deleted_at (soft delete, R6)
--   * deleted documents cannot be restored by app users
-- =========================================================================
create or replace function public.documents_guard_update()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  -- Only enforce for app roles; service_role / owners keep full access (R9)
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if new.created_by is distinct from old.created_by then
    raise exception 'created_by cannot be changed'
      using errcode = '42501';
  end if;

  if new.deleted_at is distinct from old.deleted_at then
    if old.deleted_at is not null then
      raise exception 'deleted documents cannot be modified'
        using errcode = '42501';
    end if;
    if old.created_by is distinct from auth.uid() then
      raise exception 'only the creator can delete this document'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

create trigger documents_guard_update
  before update on public.documents
  for each row
  execute function public.documents_guard_update();

-- =========================================================================
-- Soft-delete RPC for creators (works even if the creator is now a viewer,
-- and avoids the "new row not visible under SELECT policy" issue).
-- =========================================================================
create or replace function public.soft_delete_document(p_document_id bigint)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  update public.documents d
     set deleted_at = now()
   where d.id = p_document_id
     and d.deleted_at is null
     and d.created_by = auth.uid()
     and public.is_team_member(d.team_id);

  get diagnostics v_count = row_count;
  return v_count > 0;
end;
$$;

revoke all on function public.soft_delete_document(bigint) from public, anon;
grant execute on function public.soft_delete_document(bigint) to authenticated;

revoke all on function public.documents_guard_update() from public, anon, authenticated;
