-- Enable RLS on profiles
alter table public.profiles enable row level security;

-- Privileges: start from least privilege for client roles
revoke all on table public.profiles from anon;
revoke all on table public.profiles from authenticated;

-- R1: everyone may read
grant select on table public.profiles to anon;
grant select on table public.profiles to authenticated;

-- R2/R3: signed-in users may insert/update (rows constrained by policies below)
-- R4/R5: no delete/truncate for anyone via the app; anon gets no write privileges
grant insert, update on table public.profiles to authenticated;

-- R6: service role keeps full access (bypasses RLS)
grant all on table public.profiles to service_role;

-- R1: Anyone (anon + authenticated) can read every profile
create policy "profiles_select_public"
  on public.profiles
  for select
  to anon, authenticated
  using (true);

-- R2: Signed-in users can create a profile only for themselves
create policy "profiles_insert_own"
  on public.profiles
  for insert
  to authenticated
  with check (
    (select auth.uid()) is not null
    and id = (select auth.uid())
  );

-- R3: Users can edit only their own profile and cannot reassign it
create policy "profiles_update_own"
  on public.profiles
  for update
  to authenticated
  using (
    (select auth.uid()) is not null
    and id = (select auth.uid())
  )
  with check (
    (select auth.uid()) is not null
    and id = (select auth.uid())
  );

-- R4: No delete policy is created, so deletes are denied for anon/authenticated
-- (delete privilege is also revoked above).
