  on public.tickets
  for insert
  to authenticated
  with check (
    requester_id = (select auth.uid())
    and status = 'open'
    and assigned_agent is null
  );

-- R5: only agents update tickets
create policy tickets_update_agents
  on public.tickets
  for update
  to authenticated
  using ((select public.is_agent()))
