    select 1
    from public.department_members dm
    where dm.department_id = p_department_id
      and dm.user_id = auth.uid()
  );
$$;

create or replace function public.is_department_manager(p_department_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.department_members dm
    where dm.department_id = p_department_id
      and dm.user_id = auth.uid()
      and dm.is_manager
  );
$$;

revoke all on function public.is_department_member(bigint)  from public, anon;
revoke all on function public.is_department_manager(bigint) from public, anon;
grant execute on function public.is_department_member(bigint)  to authenticated, service_role;
grant execute on function public.is_department_manager(bigint) to authenticated, service_role;

-- =========================================================
-- decide_expense
-- =========================================================
create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid        uuid := auth.uid();
  v_is_service boolean := coalesce(auth.role() = 'service_role', false);
  v_expense    public.expenses%rowtype;
begin
  if p_expense_id is null or p_approve is null then
    raise exception 'expense id and decision are required';
  end if;

  if not v_is_service and v_uid is null then
    raise exception 'not authorized';
  end if;

  select * into v_expense
  from public.expenses e
  where e.id = p_expense_id
  for update;

  if not found then
    raise exception 'expense not found or not authorized';
  end if;

  if v_is_service then
    if v_expense.status <> 'pending' then
      raise exception 'expense is not pending';
    end if;

    update public.expenses
       set status     = case when p_approve then 'approved' else 'rejected' end,
           decided_by = null
     where id = p_expense_id;
    return;
  end if;

  if not exists (
    select 1
    from public.department_members dm
    where dm.department_id = v_expense.department_id
      and dm.user_id = v_uid
      and dm.is_manager
  ) then
    raise exception 'expense not found or not authorized';
  end if;

  if v_expense.status <> 'pending' then
    raise exception 'expense is not pending';
  end if;

  if v_expense.submitted_by = v_uid then
    raise exception 'cannot decide your own expense';
  end if;

  update public.expenses
     set status     = case when p_approve then 'approved' else 'rejected' end,
         decided_by = v_uid
   where id = p_expense_id;
end;
$$;

revoke all on function public.decide_expense(bigint, boolean) from public, anon;
grant execute on function public.decide_expense(bigint, boolean) to authenticated, service_role;

