   where e.id = p_expense_id
   for update;

  if not found then
    raise exception 'expense not found or not authorized'
      using errcode = 'P0002';
  end if;

  if not v_is_service then
    if not exists (
      select 1
      from public.department_members dm
      where dm.department_id = v_expense.department_id
        and dm.user_id = v_uid
        and dm.is_manager
    ) then
      raise exception 'expense not found or not authorized'
        using errcode = '42501';
    end if;

    if v_expense.submitted_by = v_uid then
      raise exception 'cannot decide your own expense'
        using errcode = '42501';
    end if;
  end if;

  if v_expense.status <> 'pending' then
    raise exception 'expense is not pending'
      using errcode = '55000';
  end if;

  update public.expenses
     set status     = case when p_approve then 'approved' else 'rejected' end,
         decided_by = case when v_is_service then null else v_uid end
   where id = p_expense_id
     and status = 'pending';

  if not found then
    raise exception 'expense is not pending'
      using errcode = '55000';
  end if;
end;
$$;

revoke all on function public.decide_expense(bigint, boolean) from public, anon;
grant execute on function public.decide_expense(bigint, boolean) to authenticated, service_role;
