-- Checks access to a project-files object path "<project id>/<file name>".
-- p_require_admin = true  -> caller must be admin of the project's org
-- p_require_admin = false -> caller must be a member of the project's org
create or replace function public.can_access_project_file(p_path text, p_require_admin boolean)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_first text;
  v_project_id bigint;
  v_org_id bigint;
begin
  if auth.uid() is null or p_path is null then
    return false;
  end if;

  v_first := split_part(p_path, '/', 1);

  -- must be "<digits>/<something>"
  if v_first !~ '^[0-9]{1,18}$' or position('/' in p_path) = 0
     or length(p_path) <= length(v_first) + 1 then
    return false;
  end if;

  v_project_id := v_first::bigint;

  select p.org_id into v_org_id
  from public.projects p
  where p.id = v_project_id;

  if v_org_id is null then
    return false;
  end if;

  return exists (
    select 1
    from public.org_members m
    where m.org_id = v_org_id
      and m.user_id = auth.uid()
      and (not p_require_admin or m.role = 'admin')
  );
end;
$$;

