begin
  if p_expense_id is null or p_approve is null then
    raise exception 'invalid arguments';
  end if;

  v_status := case when p_approve then 'approved' else 'rejected' end;

  select * into v_expense
  from public.expenses e
  where e.id = p_expense_id
  for update;

  if not found then
    raise exception 'expense not found';
  end if;

  if v_expense.status <> 'pending' then
    raise exception 'expense is not pending';
  end if;

  if v_role = 'service_role' then
    update public.expenses
       set status = v_status,
           decided_by = null
     where id = p_expense_id;
    return;
  end if;

  if v_role is distinct from 'authenticated' or v_uid is null then
    raise exception 'not authorized';
  end if;

  if v_expense.submitted_by = v_uid then
    raise exception 'cannot decide own expense';
  end if;

  if not exists (
    select 1
    from public.department_members dm
    where dm.department_id = v_expense.department_id
      and dm.user_id = v_uid
      and dm.is_manager
  ) then
    raise exception 'not a manager of this department';
  end if;

  update public.expenses
     set status = v_status,
         decided_by = v_uid
   where id = p_expense_id;
end;
$$;

