-- Storage path helpers: first path segment must be a numeric project id
create or replace function public.can_read_project_path(p_name text)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  seg text;
begin
  if auth.uid() is null or p_name is null then
    return false;
  end if;
  seg := split_part(p_name, '/', 1);
  if seg !~ '^[0-9]{1,18}$' or position('/' in p_name) = 0 then
    return false;
  end if;
  return exists (
    select 1
    from public.projects p
    join public.org_members m on m.org_id = p.org_id
    where p.id = seg::bigint
      and m.user_id = auth.uid()
  );
end;
$$;

