-- Enable RLS on profiles
alter table public.profiles enable row level security;

-- R1: Anyone (anon + authenticated) can read every profile
create policy "profiles_select_public"
  on public.profiles
  for select
  to anon, authenticated
  using (true);

-- R2: Signed-in users can create a profile only for themselves
create policy "profiles_insert_own"
  on public.profiles
  for insert
  to authenticated
  with check (
    (select auth.uid()) is not null
    and id = (select auth.uid())
  );

-- R3: Users can edit only their own profile and cannot reassign it
create policy "profiles_update_own"
  on public.profiles
  for update
  to authenticated
  using (
    (select auth.uid()) is not null
    and id = (select auth.uid())
  )
  with check (
    (select auth.uid()) is not null
    and id = (select auth.uid())
  );

-- R4: No delete policy is created, so deletes are denied for anon/authenticated.
-- Defense in depth: also remove the privileges themselves.
revoke delete, truncate on public.profiles from anon, authenticated;

-- R5: Anonymous visitors cannot create or change profiles
revoke insert, update, delete, truncate, references, trigger on public.profiles from anon;
grant select on public.profiles to anon;

-- Authenticated users need the base privileges the policies govern
