grant update (display_name) on table public.profiles to authenticated;  -- R2: is_agent and id not updatable

revoke all on table public.tickets from authenticated;
grant select, insert, update on table public.tickets to authenticated;  -- no delete (R6)

-- Service role keeps full access (R9)
grant all on table public.profiles to service_role;
grant all on table public.tickets to service_role;

