-- =========================================================================
-- Guard trigger: never leave an organization without an owner (handles
-- concurrent leave/remove/demote races by serializing on the org row).
-- Service role and cascading org deletes are not restricted.
-- =========================================================================

create function public.org_members_keep_owner()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') = 'service_role'
     or current_user in ('postgres', 'service_role', 'supabase_admin') then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if old.role = 'owner'
     and (tg_op = 'DELETE' or new.role <> 'owner') then
    -- serialize concurrent changes on the same org
    perform 1 from public.orgs o where o.id = old.org_id for update;
    if not found then
      -- org itself is being deleted (cascade)
      return case when tg_op = 'DELETE' then old else new end;
    end if;

    if not exists (
      select 1
      from public.org_members m
      where m.org_id = old.org_id
        and m.role = 'owner'
        and m.user_id <> old.user_id
    ) then
      raise exception 'an organization must keep at least one owner';
    end if;
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

