create policy invoices_delete
  on public.invoices
  for delete
  to authenticated
  using (created_by = auth.uid() and status = 'draft');

-- Transition / immutability enforcement (R3, R4, R6); service role exempt (R9)
create or replace function public.invoices_guard_update()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if current_user not in ('anon', 'authenticated') or auth.role() = 'service_role' then
    return new;
  end if;

  -- R6
  if new.created_by is distinct from old.created_by then
    raise exception 'created_by cannot be changed';
  end if;

  if new.id is distinct from old.id then
    raise exception 'id cannot be changed';
  end if;

  -- R3: customer/amount frozen once not a draft
  if old.status <> 'draft'
     and (new.customer is distinct from old.customer
          or new.amount is distinct from old.amount) then
    raise exception 'customer and amount cannot be changed once invoice is not a draft';
  end if;

  -- Only the creator may edit a draft
  if old.status = 'draft' and old.created_by is distinct from auth.uid() then
    raise exception 'only the creator can edit a draft invoice';
  end if;

  -- R3 / R4: status transitions
  if new.status is distinct from old.status then
    if old.status = 'draft' and new.status = 'sent'
       and old.created_by = auth.uid() then
      null; -- allowed
    elsif old.status = 'sent' and new.status in ('paid', 'void')
       and public.is_finance_staff() then
      null; -- allowed
    else
      raise exception 'invalid status transition from % to %', old.status, new.status;
    end if;
  end if;

  return new;
end;
$$;

create trigger invoices_guard_update
  before update on public.invoices
  for each row
  execute function public.invoices_guard_update();
