-- Trigger: enforce field immutability and status transitions
-- =========================================================
create or replace function public.invoices_enforce_update_rules()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  -- R9: service role / non-API roles are not bound by these rules
  if coalesce(auth.role(), '') = 'service_role'
     or current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  -- identity of the row cannot change
  if new.id is distinct from old.id then
    raise exception 'invoice id cannot be changed';
  end if;

  -- R6: creator is immutable
  if new.created_by is distinct from old.created_by then
    raise exception 'created_by cannot be changed';
  end if;

  -- R3: customer/amount only editable while draft, by creator
  if new.customer is distinct from old.customer
     or new.amount is distinct from old.amount then
    if old.status <> 'draft' then
      raise exception 'customer and amount cannot change once invoice is not a draft';
    end if;
    if old.created_by is distinct from auth.uid() then
      raise exception 'only the creator can edit a draft invoice';
    end if;
  end if;

  -- R3/R4: allowed status transitions
  if new.status is distinct from old.status then
    if old.status = 'draft' and new.status = 'sent' then
      if old.created_by is distinct from auth.uid() then
        raise exception 'only the creator can send a draft invoice';
      end if;
    elsif old.status = 'sent' and new.status in ('paid', 'void') then
      if not public.is_finance_staff() then
        raise exception 'only finance staff can mark an invoice paid or void';
      end if;
    else
      raise exception 'status change from % to % is not allowed', old.status, new.status;
    end if;
  end if;

  return new;
end;
$$;

