-- =========================================================
alter table public.events enable row level security;
alter table public.delegations enable row level security;

-- =========================================================
-- Privileges
-- =========================================================
revoke all on public.events from anon;
revoke all on public.delegations from anon;
grant select, insert, update, delete on public.events to authenticated;
grant select, insert, update, delete on public.delegations to authenticated;
grant all on public.events to service_role;
grant all on public.delegations to service_role;

-- =========================================================
-- Helper: does the current user hold an unexpired delegation
-- for the given grantor (optionally requiring edit rights)?
-- =========================================================
create or replace function public.has_active_delegation(p_grantor uuid, p_need_edit boolean)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.delegations d
    where d.grantor_id = p_grantor
      and d.delegate_id = auth.uid()
      and (d.expires_at is null or d.expires_at > now())
      and (not p_need_edit or d.can_edit)
  );
$$;

revoke all on function public.has_active_delegation(uuid, boolean) from public;
revoke all on function public.has_active_delegation(uuid, boolean) from anon;
grant execute on function public.has_active_delegation(uuid, boolean) to authenticated, service_role;

-- =========================================================
-- R2: owner_id can never change
-- =========================================================
create or replace function public.events_prevent_owner_change()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.owner_id is distinct from old.owner_id then
    raise exception 'owner_id of an event cannot be changed';
  end if;
  return new;
end;
$$;

create trigger events_prevent_owner_change
  before update on public.events
  for each row
  execute function public.events_prevent_owner_change();

-- =========================================================
-- events policies
-- =========================================================
create policy events_select on public.events
  for select to authenticated
  using (
    owner_id = (select auth.uid())
    or (not is_private and public.has_active_delegation(owner_id, false))
  );

create policy events_insert on public.events
  for insert to authenticated
  with check (
    owner_id = (select auth.uid())
    or (not is_private and public.has_active_delegation(owner_id, true))
  );

create policy events_update on public.events
  for update to authenticated
  using (
    owner_id = (select auth.uid())
    or (not is_private and public.has_active_delegation(owner_id, true))
  )
  with check (
    owner_id = (select auth.uid())
    or (not is_private and public.has_active_delegation(owner_id, true))
  );

create policy events_delete on public.events
  for delete to authenticated
  using (
    owner_id = (select auth.uid())
    or (not is_private and public.has_active_delegation(owner_id, true))
  );

-- =========================================================
-- delegations policies
-- =========================================================
create policy delegations_select on public.delegations
  for select to authenticated
  using (
    grantor_id = (select auth.uid())
    or delegate_id = (select auth.uid())
  );

create policy delegations_insert on public.delegations
  for insert to authenticated
  with check (grantor_id = (select auth.uid()));

create policy delegations_update on public.delegations
  for update to authenticated
  using (grantor_id = (select auth.uid()))
  with check (grantor_id = (select auth.uid()));

create policy delegations_delete on public.delegations
  for delete to authenticated
  using (grantor_id = (select auth.uid()));

-- =========================================================
-- R4: busy_slots view (runs with owner rights, filtered explicitly)
-- =========================================================
create view public.busy_slots
with (security_invoker = false, security_barrier = true)
as
  select e.owner_id, e.starts_at, e.ends_at
  from public.events e
  where auth.role() = 'service_role'
     or (
       auth.uid() is not null
       and (
         e.owner_id = auth.uid()
         or exists (
           select 1
           from public.delegations d
           where d.grantor_id = e.owner_id
             and d.delegate_id = auth.uid()
             and (d.expires_at is null or d.expires_at > now())
         )
       )
     );

revoke all on public.busy_slots from public;
revoke all on public.busy_slots from anon;
revoke all on public.busy_slots from authenticated;
grant select on public.busy_slots to authenticated;
grant select on public.busy_slots to service_role;
