-- Enable RLS
alter table public.posts enable row level security;
alter table public.comments enable row level security;

-- Privileges: start from nothing, then grant only what the rules allow
revoke all on table public.posts from anon, authenticated;
revoke all on table public.comments from anon, authenticated;

grant select on table public.posts to anon, authenticated;
grant insert, update, delete on table public.posts to authenticated;

grant select on table public.comments to anon, authenticated;
grant insert, delete on table public.comments to authenticated;

grant usage, select on sequence public.comments_id_seq to authenticated;

-- ===================== POSTS =====================

-- R1 + R2: anyone reads live posts; authors read all of their own
create policy posts_select_live_or_own
  on public.posts
  for select
  to anon, authenticated
  using (
    (
      published_at is not null
      and published_at <= now()
      and (unpublish_at is null or unpublish_at > now())
    )
    or author_id = (select auth.uid())
  );

-- R3: insert only as yourself
create policy posts_insert_own
  on public.posts
  for insert
  to authenticated
  with check (author_id = (select auth.uid()));

-- R3: edit only your own posts, cannot hand to another author
create policy posts_update_own
  on public.posts
  for update
  to authenticated
  using (author_id = (select auth.uid()))
  with check (author_id = (select auth.uid()));

-- R3: delete only your own posts
create policy posts_delete_own
  on public.posts
  for delete
  to authenticated
  using (author_id = (select auth.uid()));

-- ===================== COMMENTS =====================

-- R4: comment visible exactly to those who can read the parent post
-- (subquery on posts is itself filtered by posts RLS)
create policy comments_select_if_post_readable
  on public.comments
  for select
  to anon, authenticated
  using (
    exists (
      select 1 from public.posts p
      where p.id = comments.post_id
    )
  );

-- R5: signed-in users comment as themselves on posts they can read
create policy comments_insert_own_on_readable_post
  on public.comments
  for insert
  to authenticated
  with check (
    author_id = (select auth.uid())
    and exists (
      select 1 from public.posts p
      where p.id = comments.post_id
    )
  );

-- R6: comment authors delete their own; post authors delete any on their posts
create policy comments_delete_own_or_post_author
  on public.comments
  for delete
  to authenticated
  using (
    author_id = (select auth.uid())
    or exists (
      select 1 from public.posts p
      where p.id = comments.post_id
        and p.author_id = (select auth.uid())
    )
  );

-- R6: no update policy on comments and no UPDATE privilege => nobody can edit
-- R7: anon has only SELECT privileges and no write policies
-- R8: service_role bypasses RLS and retains its default privileges
```

