-- =========================================================
-- Race-safe guard: user actions may never leave an org without an owner
-- =========================================================
create or replace function public.rls_guard_last_owner()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_other_owners bigint;
begin
  -- service role / server-side code (no end-user context) is unrestricted (R9)
  if auth.uid() is null then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;

  if old.role = 'owner'
     and (tg_op = 'DELETE' or new.role is distinct from 'owner') then
    -- serialize owner changes per org
    perform 1 from public.orgs o where o.id = old.org_id for update;
    if not found then
      if tg_op = 'DELETE' then return old; else return new; end if;
    end if;

    select count(*) into v_other_owners
    from public.org_members m
    where m.org_id = old.org_id
      and m.role = 'owner'
      and m.user_id <> old.user_id;

    if v_other_owners = 0 then
      raise exception 'An organization must keep at least one owner'
        using errcode = '42501';
    end if;
  end if;

  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$$;

revoke all on function public.rls_guard_last_owner() from public, anon, authenticated;

create trigger org_members_guard_last_owner
before delete or update of role on public.org_members
for each row
execute function public.rls_guard_last_owner();
